package br.com.onda;
import java.net.*;
import java.util.*;
/** One explicit provider per URL; no third-party download servers. */
final class MediaDownloads {
 static YoutubeDownloads.Result inspect(String input)throws Exception{String url=MediaLinks.resolve(input);if(MediaLinks.isTikTok(url)){MediaSession session=new MediaSession();PublicMediaHttp.Page page=PublicMediaHttp.readTikTok(url,session);String id=MediaLinks.videoId(page.url);if(id.isEmpty()){String target=shortTarget(page);if(!target.isEmpty()){page=PublicMediaHttp.readTikTok(target,session);id=MediaLinks.videoId(page.url);}}if(id.isEmpty())throw new Exception("O link curto não levou a um vídeo público do TikTok. Pode estar expirado ou exigir verificação.");TiktokPage.Clip clip;try{clip=TiktokPage.parse(page.text(),id);}catch(Exception first){String clean=MediaLinks.tiktok(page.url);if(clean.equals(page.url)&&!page.text().contains("webapp.reflow.video.detail"))throw first;page=PublicMediaHttp.readTikTok(clean,session);clip=TiktokPage.parse(page.text(),id);}final MediaSession current=session;return tiktok(available(clip,page.url,(candidate,referer)->PublicMediaHttp.readMediaPrefix(candidate,referer,current)),page.url,session.snapshot());}
  if(MediaLinks.isYoutube(url))return YoutubeDownloads.inspect(url);
  String extension=MediaLinks.extension(url);if(extension.isEmpty())return fromPublicPage(PublicMediaHttp.readPage(url),PublicMediaHttp::readMediaPrefix);
  PublicMediaHttp.Page page=PublicMediaHttp.read(url,false);if(!PublicMediaHttp.mediaHeader(page.bytes,extension))throw new Exception("O endereço não retornou um arquivo "+extension.toUpperCase(Locale.ROOT)+" reconhecível.");String name=new URI(url).getPath();name=name.substring(name.lastIndexOf('/')+1);return new YoutubeDownloads.Result(name,fileOptions(page,extension,"",""));
 }
 static String shortTarget(PublicMediaHttp.Page page){try{if(page.bytes.length>65536||!MediaLinks.videoId(page.url).isEmpty()||!MediaLinks.isTikTok(page.url))return "";URI location=new URI(page.url);String host=location.getHost();if(!host.equals("vt.tiktok.com")&&!host.equals("vm.tiktok.com")&&!location.getPath().startsWith("/t/"))return "";String html=page.text();if(!html.toLowerCase(Locale.ROOT).matches("(?s).*(redirect|moved).*"))return "";java.util.regex.Matcher links=java.util.regex.Pattern.compile("<a\\b[^>]*href\\s*=\\s*['\"]([^'\"]+)['\"]",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(html);LinkedHashSet<String> targets=new LinkedHashSet<>();while(links.find())try{String value=MediaLinks.tiktok(links.group(1).replace("&amp;","&"));if(!MediaLinks.videoId(value).isEmpty())targets.add(value);}catch(Exception ignored){}return targets.size()==1?targets.iterator().next():"";}catch(Exception ignored){return "";}}
 static List<YoutubeDownloads.Option> fileOptions(PublicMediaHttp.Page page,String extension,String referer,String label){List<YoutubeDownloads.Option> out=new ArrayList<>();out.add(new YoutubeDownloads.Option(label+extension.toUpperCase(Locale.ROOT)+" • arquivo original",page.url,null,extension,mime(extension),true,referer));if(!extension.equals("mp3")){out.add(new YoutubeDownloads.Option(label+"MP3 • extrair áudio AAC e converter • taxa configurada",page.url,null,"mp3","audio/mpeg",false,referer));if(!extension.equals("m4a"))out.add(new YoutubeDownloads.Option(label+"M4A • extrair áudio AAC",page.url,null,"m4a","audio/mp4",false,referer));if(!extension.equals("aac"))out.add(new YoutubeDownloads.Option(label+"AAC • extrair sem recodificar",page.url,null,"aac","audio/aac",false,referer));}return out;}
 static YoutubeDownloads.Result fromPublicPage(PublicMediaHttp.Page page,PrefixReader reader)throws Exception{
  PublicMediaPage parsed=PublicMediaPage.parse(page.text(),page.url);List<YoutubeDownloads.Option> options=new ArrayList<>();long deadline=System.currentTimeMillis()+45000;int checked=0,found=0;
  for(PublicMediaPage.Candidate candidate:parsed.media){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Análise cancelada");if(checked++>=6||found>=3||System.currentTimeMillis()>deadline)break;try{PublicMediaHttp.Page file=reader.read(candidate.url,page.url);String type=PublicMediaPage.fromMime(file.type);String extension=type.isEmpty()?candidate.extension:type;if(!PublicMediaHttp.mediaHeader(file.bytes,extension))continue;found++;options.addAll(fileOptions(file,extension,page.url,"Fonte "+found+" • "));}catch(java.io.InterruptedIOException error){if(Thread.currentThread().isInterrupted())throw error;}catch(Exception ignored){}}
  if(options.isEmpty())throw new java.io.IOException("A página não disponibilizou um arquivo MP4, MP3, M4A ou AAC acessível. Players carregados por scripts, login, DRM e listas HLS/DASH não são suportados por esta análise. Tente o link direto do arquivo.");return new YoutubeDownloads.Result(parsed.title,options);
 }

 interface PrefixReader {PublicMediaHttp.Page read(String url,String referer)throws Exception;}
 static TiktokPage.Clip available(TiktokPage.Clip clip,String page)throws Exception{return available(clip,page,PublicMediaHttp::readMediaPrefix);}
 static TiktokPage.Clip available(TiktokPage.Clip clip,String page,PrefixReader reader)throws Exception{String referer=MediaLinks.tiktok(page);String last="";long deadline=System.currentTimeMillis()+45000;for(String candidate:clip.candidates){if(System.currentTimeMillis()>deadline)break;if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Consulta cancelada");try{PublicMediaHttp.Page prefix=reader.read(candidate,referer);if(PublicMediaHttp.mediaHeader(prefix.bytes,"mp4"))return new TiktokPage.Clip(clip.title,prefix.url);last="O endereço retornou uma página em vez do vídeo.";}catch(java.io.InterruptedIOException interrupted){if(Thread.currentThread().isInterrupted())throw interrupted;last="Tempo limite ao conferir o arquivo.";}catch(Exception error){last=error.getMessage();}}throw new Exception("O TikTok informou o vídeo, mas não liberou nenhum dos arquivos públicos consultados. "+last);}
 static YoutubeDownloads.Result tiktok(TiktokPage.Clip clip,String page)throws Exception{return tiktok(clip,page,"");}
 static YoutubeDownloads.Result tiktok(TiktokPage.Clip clip,String page,String cookies)throws Exception{String id=MediaLinks.videoId(page);if(id.isEmpty())throw new Exception("Vídeo inválido");String referer=MediaLinks.tiktok(page);List<YoutubeDownloads.Option> options=new ArrayList<>();options.add(new YoutubeDownloads.Option("TikTok • MP4 original",clip.video,null,"mp4","video/mp4",true,referer,false,cookies));options.add(new YoutubeDownloads.Option("MP3 • áudio do vídeo • taxa configurada",clip.video,null,"mp3","audio/mpeg",false,referer,false,cookies));options.add(new YoutubeDownloads.Option("M4A • extrair áudio AAC do vídeo",clip.video,null,"m4a","audio/mp4",false,referer,false,cookies));return new YoutubeDownloads.Result(clip.title,options);}
 static String mime(String extension){return extension.equals("mp3")?"audio/mpeg":extension.equals("aac")?"audio/aac":extension.equals("m4a")?"audio/mp4":"video/mp4";}
}
